class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        java.util.Arrays.fill(ans, -1);
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>(); // indices

        for (int i = 0; i < 2 * n; i++) {
            int cur = nums[i % n];
            while (!stack.isEmpty() && nums[stack.peek()] < cur) {
                ans[stack.pop()] = cur;
            }
            if (i < n) {
                stack.push(i);
            }
        }
        return ans;
    }
}

